INSERT INTO espen_tables VALUES ('Afro_LF_SiteLevel', '[{"Name": "Source", "Description": "Data source :AFRO Mapping project, GAHI or ESPEN"}, {"Name": "Date_entry", "Description": "Date for data entry"}, {"Name": "Region", "Description": "Based on the United Nations geoscheme"}, {"Name": "Country", "Description": "Country name"}, {"Name": "Country_ID", "Description": "Country code "}, {"Name": "ISO2", "Description": "ISO 2 CODE (two characters)"}, {"Name": "ISO3", "Description": "ISO 3 CODE (three characters)"}, {"Name": "ADMIN1_NAME", "Description": "ADMIN 1 name"}, {"Name": "ADMIN1_CODE", "Description": "ADMIN 1 ID"}, {"Name": "ADMIN2_NAME", "Description": "ADMIN 2 name"}, {"Name": "ADMIN2_CODE", "Description": "ADMIN 2 ID"}, {"Name": "EU_NAME", "Description": "Name of evaluation unit"}, {"Name": "IU_NAME", "Description": "Name of implementation unit"}, {"Name": "IU_ID", "Description": "ID IU"}, {"Name": "LocationName", "Description": "Original name refered in the source of data "}, {"Name": "NamePositioning", "Description": "Name finally assigned to this location after geo-referencing"}, {"Name": "Latitude", "Description": "Longitude (in decimal degrees) Datum: GCS84"}, {"Name": "Longitude", "Description": "Latitude (in decimal degrees) Datum: GCS84"}, {"Name": "Georeliability", "Description": "0 = Site name provided but not found suitable geographical coordinates                                                                                                                                                                                                                                                                               1 = Reliable: Exact location identified (within assigned IU)\n2 = Reliable: Approx. location identified (within ADMIN1)\n3 = Unreliable: Coordinates not within the correct ADM1 boundary (but within assigned country)                                                                                                                            